-- Keep the identity sequence ahead of all manually/imported contract numbers.
-- The column is already GENERATED BY DEFAULT AS IDENTITY; only its sequence state drifted.
select setval(
  pg_get_serial_sequence('public.rental_contracts', 'contract_number'),
  greatest(
    coalesce((select max(contract_number) from public.rental_contracts), 0),
    (select last_value from public.rental_contracts_contract_number_seq)
  ),
  true
);
